begin;
create extension if not exists pgtap with schema extensions;
select plan(44);
select has_table('public','families','families exist');
select has_table('public','people','people exist');
select has_table('public','family_members','members exist');
select has_table('public','cases','cases exist');
select has_table('public','case_categories','categories exist');
select has_column('public','families','address','family profile has address');
select has_column('public','families','monthly_income','family profile has monthly income');
select has_column('public','families','health_condition','family profile has health condition');
select has_column('public','families','branch_area','family profile has branch or area');
select has_column('public','families','file_status','family profile has status');
select has_column('public','families','status_reason','family profile has status reason');
insert into auth.users(id) select ('30000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,3) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('40000000-0000-0000-0000-00000000000' || n)::uuid, ('30000000-0000-0000-0000-00000000000' || n)::uuid, now(), now() from generate_series(1,3) n;
insert into public.employees(id,employee_code,display_name,role) values ('50000000-0000-0000-0000-000000000001','CASEW','Writer','employee'),('50000000-0000-0000-0000-000000000002','CASER','Reader','employee'),('50000000-0000-0000-0000-000000000003','CASEN','None','employee');
insert into private.employee_auth(employee_id,auth_user_id) select ('50000000-0000-0000-0000-00000000000' || n)::uuid, ('30000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,3) n;
insert into public.employee_permissions(employee_id,cases_write,cases_read) values ('50000000-0000-0000-0000-000000000001',true,false),('50000000-0000-0000-0000-000000000002',false,true);
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","session_id":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into public.families(name,phone,notes) values ('case-test-one','01012345678','families-cases-one'),('case-test-two','01098765432','families-cases-two')$$,'writer inserts families');
select is((select count(distinct code)::int from public.families where notes in ('families-cases-one','families-cases-two')),2,'generated codes unique in one statement');
select is((select file_status from public.families where notes='families-cases-two'),'تحت المراجعة','new profile defaults to review');
select ok((select code from public.families where notes='families-cases-one') like 'F-%','code has approved prefix');
select throws_ok($$update public.families set code='F-0001'$$,'42501',null,'code cannot be updated');
select throws_ok($$insert into public.families(name,code,phone) values ('x','F-0001','01012345678')$$,'42501',null,'code cannot be supplied');
select throws_ok($$delete from public.families$$,'42501',null,'family code history cannot be deleted');
select lives_ok($$select public.add_family_member((select id from public.families where notes='families-cases-one'),'person-families-cases','ابن')$$,'writer adds household member');
select throws_ok($$update public.families set file_status='موقوف',status_reason=null where notes='families-cases-one'$$,'23514',null,'hold requires reason');
select throws_ok($$update public.families set file_status='مرفوض',status_reason='   ' where notes='families-cases-one'$$,'23514',null,'rejected requires a nonempty reason');
select lives_ok($$update public.families set address='عنوان تجريبي',monthly_income=2500,health_condition='تحتاج متابعة',branch_area='فرع وسط البلد',file_status='موقوف',status_reason='استكمال المستندات' where notes='families-cases-one'$$,'profile fields and reason save');
select throws_ok($$update public.families set monthly_income=-1 where notes='families-cases-one'$$,'23514',null,'negative income rejected');
select is((select count(*)::int from public.family_members fm join public.families f on f.id=fm.family_id where f.notes='families-cases-one'),1,'membership saved');
select lives_ok($$select public.save_case_file((select id from public.families where notes='families-cases-one'),'{"mother_name":"أم وهمية","phone":"01012345678","notes":"families-cases-one"}'::jsonb,array['هجر','يتيم الأم'])$$,'writer adds categories to the family case file');
select is((select count(*)::int from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one')),2,'both categories persist on one profile');
select throws_ok($$select public.save_case_file((select id from public.families where notes='families-cases-one'),'{"mother_name":"أم وهمية","phone":"01012345678","notes":"families-cases-one"}'::jsonb,array['غير معروف'])$$,'42501',null,'unknown category rejected by write policy');
select is((select count(*)::int from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one')),2,'invalid category rolls back');
select lives_ok($$select public.save_case_file((select id from public.families where notes='families-cases-one'),'{"mother_name":"أم معدلة","phone":"01012345678","notes":"families-cases-one"}'::jsonb,array['يتيم الأب','مطلقة'])$$,'writer updates the same profile and categories');
select is((select string_agg(category,',' order by category) from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one')),'مطلقة,يتيم الأب','profile categories replaced together');
reset role;
insert into public.case_file_categories(family_id,category) select id,'وفاة' from public.families where notes='families-cases-one';
set local role authenticated;
select lives_ok($$select public.save_case_file((select id from public.families where notes='families-cases-one'),'{"mother_name":"أم جديدة","phone":"01012345678","notes":"families-cases-one"}'::jsonb,array['أرملة'])$$,'editing current categories succeeds with an archived category present');
select is((select count(*)::int from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one') and category='وفاة'),1,'editing preserves an archived category');
select throws_ok($$select public.save_case_file(null,'{"mother_name":"أم جديدة","phone":"01012345678"}'::jsonb,array['وفاة'])$$,'42501',null,'removed historical category cannot be added to a new profile');
select throws_ok($$select public.save_case_file(null,'{"father_name":"أب"}'::jsonb,array[]::text[])$$,'23514',null,'new profile requires mother name');
select throws_ok($$select public.save_case_file((select id from public.families where notes='families-cases-one'),'{"mother_name":"أم جديدة","phone":"01012345678","notes":"families-cases-one"}'::jsonb,array['غير معروف'])$$,'42501',null,'invalid profile edit rejected by write policy');
select is((select count(*)::int from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one')),2,'failed edit preserves original categories');
reset role;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000002","session_id":"40000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.families where notes in ('families-cases-one','families-cases-two')),2,'reader sees families');
select is((select count(*)::int from public.people where name='person-families-cases'),1,'reader sees people');
select is((select count(*)::int from public.family_members fm join public.families f on f.id=fm.family_id where f.notes='families-cases-one'),1,'reader sees members');
select is((select count(*)::int from public.case_file_categories where family_id=(select id from public.families where notes='families-cases-one')),2,'reader sees profile categories');
select throws_ok($$select * from public.cases$$,'42501',null,'legacy cases are archived from staff');
select throws_ok($$insert into public.families(name,phone) values ('x','01012345678')$$,'42501',null,'reader cannot insert');
select throws_ok($$select public.save_case(null,(select id from public.families limit 1),'',array['هجر'])$$,'42501',null,'reader cannot save case');
reset role;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000003","session_id":"40000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select (select count(*) from public.families)+(select count(*) from public.people)+(select count(*) from public.family_members)+(select count(*) from public.case_file_categories))::int,0,'unprivileged user sees no domain rows');
select * from finish(); rollback;
